diff --git a/src/io/sales-import.js b/src/io/sales-import.js
new file mode 100644
index 0000000..a9feb6d
--- /dev/null
+++ b/src/io/sales-import.js
@@ -0,0 +1,91 @@
+// Importing till sales from CSV (ticket,soldAt,dishId,qty).
+// Tickets already imported are skipped; any invalid row or stock shortage
+// aborts the whole file and names the offending row.
+import { isInstant } from "../dates.js";
+import { consume } from "../domain/batches.js";
+import { getItem, onHand } from "../domain/items.js";
+import { scaled } from "../domain/recipes.js";
+import { AppError } from "../errors.js";
+import { parseCsv } from "./csv.js";
+
+const HEADER = ["ticket", "soldAt", "dishId", "qty"];
+
+/** Imports till sales from CSV; returns { tickets, dishes } or throws naming the row. */
+export function importSales(store, text) {
+  const [head, ...rawRows] = parseCsv(text);
+  if (!head) throw new AppError("bad_request", { reason: "empty csv" });
+  const keys = head.map((h) => h.trim());
+  for (const k of HEADER) {
+    if (!keys.includes(k)) throw new AppError("bad_request", { reason: `missing column ${k}` });
+  }
+
+  const clean = rawRows.map((raw, i) => {
+    const where = `row ${i + 2}`;
+    if (raw.length !== keys.length) throw new AppError("bad_request", { reason: `${where}: wrong column count` });
+    const r = Object.fromEntries(keys.map((k, idx) => [k, (raw[idx] ?? "").trim()]));
+    if (!r.ticket) throw new AppError("bad_request", { reason: `${where}: ticket is required` });
+    if (!isInstant(r.soldAt)) throw new AppError("bad_request", { reason: `${where}: bad soldAt` });
+    const dishId = r.dishId === "" ? NaN : Number(r.dishId);
+    if (!Number.isInteger(dishId) || dishId < 1) throw new AppError("bad_request", { reason: `${where}: bad dishId` });
+    const dish = (store.data.dishes ?? []).find((d) => d.id === dishId);
+    if (!dish) throw new AppError("bad_request", { reason: `${where}: unknown dish` });
+    const recipe = store.data.recipes.find((rec) => rec.id === dish.recipeId);
+    if (!recipe) throw new AppError("bad_request", { reason: `${where}: unknown recipe` });
+    const qty = r.qty === "" ? NaN : Number(r.qty);
+    if (!Number.isInteger(qty) || qty < 1) throw new AppError("bad_request", { reason: `${where}: bad qty` });
+    return { where, ticket: r.ticket, soldAt: r.soldAt, dishId, recipe, qty };
+  });
+
+  const imported = new Set((store.data.sales ?? []).map((s) => s.ticket));
+  const toImport = clean.filter((r) => !imported.has(r.ticket));
+  if (!toImport.length) return { tickets: 0, dishes: 0 };
+
+  const snapshot = structuredClone(store.data);
+  let currentWhere = "";
+  try {
+    store.data.sales ??= [];
+    for (const r of toImport) {
+      currentWhere = r.where;
+      const needs = scaled(r.recipe, r.qty);
+      const byItem = new Map();
+      for (const n of needs) {
+        if (n.qty > 0) byItem.set(n.itemId, Math.round(((byItem.get(n.itemId) ?? 0) + n.qty) * 1000) / 1000);
+      }
+      for (const [itemId, needQty] of byItem) {
+        const item = getItem(store, itemId);
+        const available = onHand(store, itemId);
+        if (available < needQty) {
+          throw new AppError("not_enough_stock", {
+            item: `${item.name} (${r.where})`,
+            available: Math.round(available * 1000) / 1000,
+            unit: item.unit,
+          });
+        }
+      }
+      for (const n of needs) {
+        if (n.qty > 0) consume(store, n.itemId, n.qty, { at: r.soldAt, ref: `sale:${r.ticket}` });
+      }
+      store.data.sales.push({
+        id: store.nextId("sale"),
+        ticket: r.ticket,
+        soldAt: r.soldAt,
+        dishId: r.dishId,
+        qty: r.qty,
+      });
+    }
+  } catch (e) {
+    store.data = snapshot;
+    if (e instanceof AppError && e.code === "not_enough_stock" && !String(e.params.item).includes(currentWhere)) {
+      throw new AppError("not_enough_stock", {
+        item: `${e.params.item} (${currentWhere})`,
+        available: e.params.available,
+        unit: e.params.unit,
+      });
+    }
+    throw e;
+  }
+
+  const tickets = new Set(toImport.map((r) => r.ticket)).size;
+  const dishes = toImport.reduce((sum, r) => sum + r.qty, 0);
+  return { tickets, dishes };
+}
